-- create "problems" table
CREATE TABLE
    "problems" (
        "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
        "title" text NOT NULL,
        "description" text NOT NULL,
        "spoiler" text NOT NULL,
        "time_limit" bigint NOT NULL,
        "memory_limit" bigint NOT NULL,
        "draft_mapping_id" bigint,
        "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "deleted_at" timestamptz,
        PRIMARY KEY ("id")
    );

CREATE TABLE
    "problem_drafts" (
        "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
        "title" text NOT NULL,
        "description" text NOT NULL,
        "spoiler" text NOT NULL,
        "time_limit" bigint NOT NULL,
        "memory_limit" bigint NOT NULL,
        "draft_mapping_id" bigint,
        "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "deleted_at" timestamptz,
        PRIMARY KEY ("id")
    );

CREATE TABLE
    "problem_draft_mappings" (
        "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
        "problem_id" bigint NOT NULL,
        "draft_id" bigint NOT NULL,
        PRIMARY KEY ("id"),
        CONSTRAINT "problem_draft_mappings_problems" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id"),
        CONSTRAINT "problem_draft_mappings_problem_drafts" FOREIGN KEY ("draft_id") REFERENCES "problem_drafts" ("id")
    );

CREATE TABLE
    "problem_testcases" (
        "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
        "problem_id" bigint NOT NULL,
        "draft_id" bigint NOT NULL,
        "input_attachment_id" bigint NOT NULL,
        "output_attachment_id" bigint NOT NULL,
        "example" boolean NOT NULL DEFAULT FALSE,
        "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "deleted_at" timestamptz,
        PRIMARY KEY ("id"),
        CONSTRAINT "problem_testcases_problems" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id"),
        CONSTRAINT "problem_testcases_problem_drafts" FOREIGN KEY ("draft_id") REFERENCES "problem_drafts" ("id")
    );

