    );

-- create "submissions" table
CREATE TYPE "submission_status" AS ENUM (
    'pending',
    'running',
    'accepted',
    'wrong_answer',
    'time_limit_exceeded',
    'memory_limit_exceeded',
    'runtime_error',
    'compile_error',
    'system_error'
);

