        "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "deleted_at" timestamptz,
        "language_id" bigint NOT NULL,
        "problem_id" bigint NOT NULL,
        "user_id" bigint NOT NULL,
        PRIMARY KEY ("id"),
        CONSTRAINT "submissions_languages_submissions" FOREIGN KEY ("language_id") REFERENCES "languages" ("id"),
        CONSTRAINT "submissions_problems_submissions" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id"),
        CONSTRAINT "submissions_users_submissions" FOREIGN KEY ("user_id") REFERENCES "users" ("id")
    );

